'use strict';
const test = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const crypto = require('node:crypto');

// A DOM surface, not a TeX mock: all expressions use the actual pinned KaTeX renderer.
class Node {
  constructor(document, tag, text) {
    this.ownerDocument = document; this.tagName = tag?.toUpperCase(); this.nodeType = tag ? 1 : 3;
    this.childNodes = []; this.attributes = {}; this.style = {}; this.className = '';
    this.parentElement = null; this.value = text || '';
  }
  appendChild(child) { child.parentElement = this; this.childNodes.push(child); return child; }
  replaceChildren(...children) { this.childNodes = []; this.value = ''; for (const child of children) this.appendChild(child); }
  setAttribute(name, value) { this.attributes[name] = String(value); }
  setAttributeNS(_namespace, name, value) { this.setAttribute(name, value); }
  getAttribute(name) { return this.attributes[name] ?? null; }
  get textContent() { return this.nodeType === 3 ? this.value : this.childNodes.map(child => child.textContent).join(''); }
  set textContent(value) { this.replaceChildren(); if (String(value)) this.appendChild(this.ownerDocument.createTextNode(String(value))); }
  set innerHTML(_) { throw new Error('HTML strings must never be assigned by the presentation layer'); }
}
const document = {
  compatMode:'CSS1Compat',
  createElement(tag) { return new Node(this, tag); },
  createElementNS(_namespace, tag) { return this.createElement(tag); },
  createTextNode(text) { return new Node(this, null, String(text)); },
  createDocumentFragment() { return new Node(this, 'fragment'); }
};
global.document = document;
const katex = require('katex');
global.katex = katex;
const presentation = require('../web/math-presentation.js');
const root = path.resolve(__dirname, '..');
const read = name => fs.readFileSync(path.join(root, name), 'utf8');
const json = name => JSON.parse(read(name));
const clone = data => JSON.parse(JSON.stringify(data));
const all = node => [node, ...node.childNodes.flatMap(all)];
const expressions = node => all(node).filter(n => n.getAttribute('data-math-state'));
const box = (tag = 'div') => document.createElement(tag);

test('All supported delimiters render synchronously using actual KaTeX', () => {
  const node = box();
  assert.equal(presentation.render(node, String.raw`A $x^2$ B $$y+1$$ C \(z\) D \[w\]`), node);
  assert.equal(expressions(node).length, 4);
  assert.ok(expressions(node).every(n => n.getAttribute('data-math-state') === 'rendered'));
  assert.equal(expressions(node).filter(n => n.className.includes('math-display')).length, 2);
  assert.ok(all(node).some(n => n.tagName === 'MATH'), 'accessible MathML is present');
  presentation.render(node, 'replacement');
  assert.equal(node.textContent, 'replacement');
});
test('Invalid TeX preserves source and neighboring prose in a readable literal fallback', () => {
  const node = box(), input = String.raw`До $\notARealCommand{x}$ после`;
  presentation.render(node, input);
  assert.equal(node.textContent, input);
  assert.equal(expressions(node)[0].getAttribute('data-math-state'), 'literal');
  presentation.formula(node, String.raw`\frac{`, {display:true});
  assert.equal(node.textContent, String.raw`\frac{`);
  assert.match(expressions(node)[0].className, /math-display.*math-fallback/);
});
test('Untrusted HTML prose remains text; TeX cannot create trusted links or HTML nodes', () => {
  const node = box(), raw = '<img src=x onerror=alert(1)><script>alert(1)</script>';
  presentation.render(node, raw);
  assert.equal(node.textContent, raw); assert.equal(node.childNodes.length, 1); assert.equal(node.childNodes[0].nodeType, 3);
  for (const tex of [String.raw`\href{javascript:alert(1)}{click}`, String.raw`\includegraphics{https://evil.invalid/x}`, String.raw`\htmlClass{attack}{x}`]) {
    presentation.formula(node, tex);
    assert.ok(!all(node).some(n => ['A','IMG','SCRIPT','IFRAME'].includes(n.tagName)));
    assert.ok(!all(node).some(n => n.className === 'attack'));
  }
});
test('Lean and inline/fenced code stay byte-for-byte literal; code ancestors are protected', () => {
  const code = String.raw`theorem dollar : True := by -- $x$ and \(y\)
  trivial`;
  for (const tag of ['pre','code','textarea']) {
    const node = box(tag); presentation.render(node, code); assert.equal(node.textContent, code); assert.equal(expressions(node).length, 0);
  }
  const parent = box('pre'), child = box('span'); parent.appendChild(child);
  presentation.formula(child, code, {display:true}); assert.equal(child.textContent, code); assert.equal(expressions(child).length, 0);
  for (const input of ['`$x$`', '```lean\n' + code + '\n```', '~~~lean\n' + code + '\n~~~', 'unclosed `$x$']) {
    const node = box(); presentation.render(node, input); assert.equal(node.textContent, input); assert.equal(expressions(node).length, 0);
  }
});
test('Escaped and unmatched delimiters remain intact, braces protect inner dollars', () => {
  const node = box();
  for (const input of [String.raw`price \$5`, 'unmatched $x', String.raw`\(x`, '$$']) {
    presentation.render(node, input); assert.equal(node.textContent, input); assert.equal(expressions(node).length, 0);
  }
  presentation.render(node, String.raw`$x+\text{cost \$5}$`);
  assert.equal(expressions(node).length, 1); assert.equal(expressions(node)[0].getAttribute('data-math-state'), 'rendered');
});
test('Macro state is isolated and expansion, size and total rendering have finite limits', () => {
  const node = box(), captured = [];
  global.katex = {render(tex, element, options) { captured.push(options); katex.render(tex, element, options); }};
  try {
    presentation.render(node, String.raw`$\gdef\atlasShared{x}\atlasShared$ and $\atlasShared$`);
    assert.equal(expressions(node)[0].getAttribute('data-math-state'), 'rendered');
    assert.equal(expressions(node)[1].getAttribute('data-math-state'), 'literal');
    assert.notEqual(captured[0].macros, captured[1].macros);
    assert.equal(captured[0].trust, false); assert.ok(Number.isFinite(captured[0].maxExpand)); assert.ok(Number.isFinite(captured[0].maxSize));
    presentation.formula(node, String.raw`\def\loop{\loop}\loop`);
    assert.equal(expressions(node)[0].getAttribute('data-math-state'), 'literal');
    const large = 'x'.repeat(presentation.limits.tex + 1);
    const before = captured.length; presentation.formula(node, large); assert.equal(captured.length, before); assert.equal(node.textContent, large);
    const longText = 'text '.repeat(presentation.limits.text); presentation.render(node, longText); assert.equal(node.textContent, longText);
    presentation.render(node, '$x$ '.repeat(presentation.limits.expressions + 5));
    assert.equal(expressions(node).length, presentation.limits.expressions); assert.ok(node.textContent.endsWith('$x$ '.repeat(5)));
  } finally { global.katex = katex; }
});

const sourceContent = read('research_fixtures/Arxiv261038474.lean');
const hash = crypto.createHash('sha256').update(sourceContent).digest('hex');
const declaration = {name:'Arxiv261038474.subtract_restore', kind:'theorem',
  type:'∀ {R : Type u_1} [inst : CommRing R] (b w : Polynomial R),\n  Arxiv261038474.compose (Arxiv261038474.graphSubtract b w) (Arxiv261038474.graphRestore b w) = MvPolynomial.X'};
function source() { return {status:'ready',inspection:{status:'complete',success:true},source_sha256:hash,content:sourceContent,declarations:[clone(declaration)]}; }
function run(contractName) {
  const contract = json('examples/common_structure/' + contractName);
  return {purpose:'prove',target:contract.target,formal_contract:contract,
    contract:{source_library:{content:sourceContent,source_sha256:hash,selected_declaration:clone(declaration)}}};
}
test('Known source summary requires exact source content, hash, inspected theorem type and successful inspection', () => {
  const original = source(), snapshot = JSON.stringify(original);
  assert.ok(presentation.sourceSummary(original, declaration.name)); assert.equal(JSON.stringify(original), snapshot);
  for (const change of [s => s.source_sha256 = '0'.repeat(64), s => s.content = s.content.replace('X 1', 'X 0'),
    s => s.declarations[0].type = 'True', s => s.declarations[0].kind = 'axiom', s => s.declarations[0].unsafe = true,
    s => s.inspection.success = false, s => delete s.content, s => s.declarations.push(clone(s.declarations[0]))]) {
    const altered = source(); change(altered); assert.equal(presentation.sourceSummary(altered, declaration.name), null);
  }
  assert.equal(presentation.sourceSummary(original, 'Other.' + declaration.name), null);
});
test('Known run summaries require the exact retained contracts, definitions and all obligations', () => {
  for (const name of ['AstraCoordinateAutomorphism.contract.json','AstraSpectrumHomeomorphism.contract.json']) {
    const original = run(name), before = JSON.stringify(original), summary = presentation.runSummary(original);
    assert.ok(summary); assert.equal(JSON.stringify(original), before);
    const inputTargetRun = clone(original); inputTargetRun.target = declaration.name;
    assert.deepEqual(presentation.runSummary(inputTargetRun), summary);
    assert.deepEqual(Object.keys(summary).sort(), ['assumptions','description','formulas','graphLabel','limitations','title']);
    assert.doesNotMatch(summary.description, /^Цель|Доказано|Проверено/); assert.equal(summary.status, undefined);
    for (const change of [r => r.formal_contract.statement = 'True', r => r.formal_contract.prelude += '\naxiom hidden : False',
      r => r.formal_contract.required_obligations.pop(), r => r.formal_contract.required_obligations[0].statement = 'True',
      r => r.formal_contract.required_obligations[0].expected_outcome = 'refuted', r => r.formal_contract.imports.push('Other'),
      r => r.contract.source_library.source_sha256 = '0'.repeat(64), r => r.contract.source_library.content += '\n-- changed',
      r => r.target = 'Foreign.target', r => r.result = {verification:{expected_statement:'True'}}]) {
      const altered = clone(original); change(altered); assert.equal(presentation.runSummary(altered), null);
    }
    const unknown = clone(original); unknown.outcome = 'unknown';
    assert.ok(presentation.runSummary(unknown)); assert.doesNotMatch(JSON.stringify(presentation.runSummary(unknown)), /Доказано|proved|success/);
    for (const item of summary.formulas) {
      const node = box(); presentation.formula(node, item.tex, {display:true});
      assert.equal(expressions(node)[0].getAttribute('data-math-state'), 'rendered');
    }
  }
  assert.equal(presentation.runSummary({id:'SpectrumBridge.coordinate_and_spectrum_equivalence',outcome:'proved'}), null);
});
test('Vendored runtime, stylesheet, all referenced fonts and license match the deterministic hash manifest', () => {
  const vendor = path.join(root, 'web/vendor/katex'), manifest = JSON.parse(fs.readFileSync(path.join(vendor, 'manifest.json')));
  assert.equal(manifest.version, require('katex/package.json').version);
  for (const [name, expected] of Object.entries(manifest.files)) {
    const bytes = fs.readFileSync(path.join(vendor, name));
    assert.equal(bytes.length, expected.bytes); assert.equal(crypto.createHash('sha256').update(bytes).digest('hex'), expected.sha256);
  }
  const css = fs.readFileSync(path.join(vendor, 'katex.min.css'), 'utf8');
  for (const match of css.matchAll(/url\(([^)]+)\)/g)) {
    const filename = match[1].replace(/^['"]|['"]$/g, '');
    assert.ok(filename.startsWith('fonts/')); assert.ok(manifest.files[filename]);
  }
  assert.ok(manifest.files['LICENSE']); assert.ok(manifest.files['katex.min.js']);
});

