function entityRuns() {
  return clone(ENTITY_CASES).map(r => ({...r,contract:{source_library:{content:sourceContent,
    source_sha256:hash,selected_declaration:clone(declaration)}}}));
}
function renderSummary(summary) {
  assert.ok(summary);
  assert.equal(typeof summary.graphLabel,'string');
  assert.ok(summary.graphLabel.length>0 && summary.graphLabel.length<=24,summary.graphLabel);
  const core=[summary.title,summary.graphLabel,summary.description,...summary.assumptions,...summary.limitations,...summary.formulas.map(f=>f.label)].join('\n');
  assert.doesNotMatch(core,/MvPolynomial|CommRing|Arxiv261038474\.|SpectrumBridge\.|Route3\.|Fin 3|eval₂/);
  for(const prose of [summary.description,...summary.assumptions,...summary.limitations]) {
    const node=box(); presentation.render(node,prose);
    assert.ok(expressions(node).every(n=>n.getAttribute('data-math-state')==='rendered'),prose);
  }
  for(const {tex} of summary.formulas) {
    const node=box(); presentation.formula(node,tex,{display:true});
    assert.equal(expressions(node)[0].getAttribute('data-math-state'),'rendered',tex);
    assert.match(expressions(node)[0].className,/math-display/);
    assert.ok(all(node).some(n=>n.tagName==='MATH'));
  }
  assert.equal(summary.status,undefined);assert.equal(summary.success,undefined);
}
test('All entities of the four retained maps render mathematical prose and TeX, never Lean identifiers',()=>{
  for(const r of entityRuns()) {
    renderSummary(presentation.runSummary(r));
    for(const [kind,values] of [['object',r.object_graph.objects],['transition',r.object_graph.transitions],['proof',r.nodes]]) {
      for(const value of values) renderSummary(presentation.entitySummary(r,kind,value));
    }
    // Data are recognized mathematically, not by a run ID or a proof-status badge.
    r.id='unrelated-looking-id';r.status='complete';r.outcome='unknown';
    const summary=presentation.entitySummary(r,'transition',r.object_graph.transitions[0]);
    assert.ok(summary);assert.equal(summary.status,undefined);
  }
});
test('Entity guards reject altered definitions, hidden hypotheses, neighboring context and counterfeit hashes',()=>{
  for(const original of entityRuns()) {
    for(const mutate of [r=>r.contract.source_library.source_sha256='0'.repeat(64),
      r=>r.contract.source_library.content=sourceContent.replace('X 1','X 0'),
      r=>r.object_graph.objects[1].definition='A = Unit',
      r=>r.object_graph.objects[1].assumptions.push('R is a field'),
      r=>r.object_graph.transitions[0].claim='True',
      r=>r.object_graph.transitions[0].target_ids=['different-object']]) {
      const changed=clone(original);mutate(changed);
      assert.equal(presentation.entitySummary(changed,'object',changed.object_graph.objects[0]),null);
      assert.equal(presentation.entitySummary(changed,'transition',changed.object_graph.transitions.at(-1)),null);
    }
    const forged=clone(original.object_graph.objects[1]);forged.definition='True';
    assert.equal(presentation.entitySummary(original,'object',forged),null);
    assert.equal(presentation.entitySummary(original,'object',{id:'unknown',definition:'F ∘ G = id'}),null);
    assert.equal(presentation.entitySummary(original,'unsupported',original.object_graph.objects[0]),null);
    if(original.formal_contract) {
      const changed=clone(original);changed.formal_contract.prelude+='\naxiom hidden : False';
      assert.equal(presentation.entitySummary(changed,'object',changed.object_graph.objects[0]),null);
      assert.equal(presentation.entitySummary(changed,'proof',changed.nodes[0]),null);
      const node=clone(original.nodes[0]);node.statement='True';
      assert.equal(presentation.entitySummary(original,'proof',node),null);
      node.statement=original.nodes[0].statement;node.target='Unknown.same_name';
      assert.equal(presentation.entitySummary(original,'proof',node),null);
    }
  }
});
test('New conjugacy presentation preserves every quantifier and return-at-n without inventing a minimal period',()=>{
  const r=entityRuns().find(r=>r.formal_contract?.target==='Route3.coordinate_conjugacy');
  const summary=presentation.runSummary(r),formulas=summary.formulas.map(f=>f.tex).join('\n'),words=summary.assumptions.join('\n');
  assert.match(words,/R,S/);assert.match(words,/\\varphi:R\\to S/);assert.match(words,/H\\in/);assert.match(words,/n\\in\\mathbb N/);
  assert.match(summary.description,/Одна биекция/);assert.match(summary.description,/любое/);
  for(const exact of [String.raw`e=\operatorname{ev}_\varphi(F)`,String.raw`e^{-1}=\operatorname{ev}_\varphi(G)`,
    String.raw`K=F\circ H\circ G`,String.raw`e\circ h^{\circ n}=k^{\circ n}\circ e`,
    String.raw`k^{\circ n}=e\circ h^{\circ n}\circ e^{-1}`]) assert.ok(formulas.includes(exact),exact);
  assert.match(formulas,/h\^\{\\circ n\}\(v\)=v/);assert.match(formulas,/k\^\{\\circ n\}\(e\(v\)\)=e\(v\)/);
  assert.doesNotMatch(formulas,/min|period|\\mathbb Z|h\^\{-1\}/);
  assert.match(summary.limitations.join(' '),/не означает.*минимальный период/);
  assert.equal(summary.formulas.filter(f=>f.featured===true).length,3);
  assert.ok(summary.formulas.filter(f=>f.featured===true).some(f=>f.label.includes('Возвращение')));
  const spectrum=entityRuns().find(r=>r.formal_contract?.target==='SpectrumBridge.coordinate_and_spectrum_equivalence');
  assert.equal(presentation.runSummary(spectrum).formulas.filter(f=>f.featured===true).length,2);
  const evaluation=r.nodes.find(n=>n.target==='Route3.eval_compose');
  const evalSummary=presentation.entitySummary(r,'proof',evaluation);
  assert.equal(evalSummary.graphLabel,'Композиция');
  assert.equal(presentation.entitySummary(r,'proof',r.nodes.find(n=>n.target==='Route3.k')).graphLabel,'Динамика k');
  assert.ok(evalSummary.formulas[0].tex.includes(String.raw`\operatorname{ev}_\varphi(P\circ Q)`));
  for(const mutate of [c=>c.required_obligations[0].statement=c.required_obligations[0].statement.split(' ∧')[0],
    c=>c.statement=c.statement.replace('∀ n : ℕ','∀ n : ℤ'),
    c=>c.statement=c.statement.replace('↔','→'),c=>c.required_obligations[1].statement='True']) {
    const changed=clone(r);mutate(changed.formal_contract);assert.equal(presentation.runSummary(changed),null);
  }
});
test('Unknown equations are never fabricated and mathematical CSS preserves readable fallback',()=>{
  assert.equal(presentation.entitySummary({id:'f5e3c278060f4b8e98fb17039789e651'},'proof',
    {target:'Route3.coordinate_conjugacy',statement:'True'}),null);
  const node=box(),raw='Неизвестная формула: A → B; new_theorem : True';
  presentation.render(node,raw);assert.equal(node.textContent,raw);assert.equal(expressions(node).length,0);
  const css=read('web/math-presentation.css');
  assert.match(css,/min-width:\s*0/);assert.match(css,/overflow-x:\s*auto/);assert.match(css,/white-space:\s*pre-wrap/);
});
